-- SumaQ on 17th central database (Supabase PostgreSQL)
-- Run once in Supabase > SQL Editor.

create extension if not exists pgcrypto;

create table if not exists public.menu_items (
 id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, category text not null, description text not null default '', price numeric(10,2) not null check(price>=0), unit text not null default 'unit', image_url text not null default '', active boolean not null default true, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.shop_products (
 id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, category text not null, description text not null default '', price numeric(10,2) not null check(price>=0), unit text not null default 'unit', image_url text not null default '', active boolean not null default true, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);

create table if not exists public.reservations (
 id uuid primary key default gen_random_uuid(), first_name text not null, last_name text not null default '', email text not null, phone text not null default '', reservation_date date not null, reservation_time time not null, adults integer not null default 0, minors integer not null default 0, party_size integer not null default 0, notes text not null default '', status text not null default 'Booked', deposit_required boolean not null default false, deposit_amount numeric(10,2) not null default 0, payment_status text not null default 'No payment required', paid_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.private_event_inquiries (
 id uuid primary key default gen_random_uuid(), first_name text not null, last_name text not null default '', email text not null, phone text not null default '', event_date date, estimated_guests integer, message text not null, status text not null default 'New', created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.orders (
 id uuid primary key default gen_random_uuid(), public_id text not null unique, order_type text not null check(order_type in ('pickup','shop')), customer_name text not null, email text not null, phone text not null default '', pickup_date date, pickup_time time, fulfillment text not null default 'Store pickup', notes text not null default '', subtotal numeric(10,2) not null default 0, tax numeric(10,2) not null default 0, total numeric(10,2) not null default 0, status text not null default 'Awaiting payment', payment_status text not null default 'Pending', stripe_session_id text, paid_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.order_items (
 id bigint generated by default as identity primary key, order_id uuid not null references public.orders(id) on delete cascade, product_slug text not null, product_name text not null, unit_price numeric(10,2) not null, quantity integer not null check(quantity>0), line_total numeric(10,2) not null, created_at timestamptz not null default now()
);

create index if not exists reservations_date_idx on public.reservations(reservation_date);
create index if not exists reservations_created_idx on public.reservations(created_at desc);
create index if not exists events_created_idx on public.private_event_inquiries(created_at desc);
create index if not exists orders_created_idx on public.orders(created_at desc);
create index if not exists order_items_order_idx on public.order_items(order_id);

alter table public.menu_items enable row level security;
alter table public.shop_products enable row level security;
alter table public.reservations enable row level security;
alter table public.private_event_inquiries enable row level security;
alter table public.orders enable row level security;
alter table public.order_items enable row level security;

drop policy if exists "Public reads active menu" on public.menu_items;
create policy "Public reads active menu" on public.menu_items for select using (active = true or auth.role() = 'authenticated');
drop policy if exists "Public reads active shop" on public.shop_products;
create policy "Public reads active shop" on public.shop_products for select using (active = true or auth.role() = 'authenticated');

-- Public inserts are performed by protected Netlify Functions using the service role.
-- Authenticated users are SumaQ administrators; disable public sign-ups in Supabase Auth.
drop policy if exists "Admin full access menu_items" on public.menu_items;
create policy "Admin full access menu_items" on public.menu_items for all to authenticated using (true) with check (true);
drop policy if exists "Admin full access shop_products" on public.shop_products;
create policy "Admin full access shop_products" on public.shop_products for all to authenticated using (true) with check (true);
drop policy if exists "Admin full access reservations" on public.reservations;
create policy "Admin full access reservations" on public.reservations for all to authenticated using (true) with check (true);
drop policy if exists "Admin full access private_event_inquiries" on public.private_event_inquiries;
create policy "Admin full access private_event_inquiries" on public.private_event_inquiries for all to authenticated using (true) with check (true);
drop policy if exists "Admin full access orders" on public.orders;
create policy "Admin full access orders" on public.orders for all to authenticated using (true) with check (true);
drop policy if exists "Admin full access order_items" on public.order_items;
create policy "Admin full access order_items" on public.order_items for all to authenticated using (true) with check (true);


drop policy if exists "Public reads product images" on storage.objects;
create policy "Public reads product images" on storage.objects for select using (bucket_id='product-images');
drop policy if exists "Admins upload product images" on storage.objects;
create policy "Admins upload product images" on storage.objects for insert to authenticated with check (bucket_id='product-images');
drop policy if exists "Admins update product images" on storage.objects;
create policy "Admins update product images" on storage.objects for update to authenticated using (bucket_id='product-images') with check (bucket_id='product-images');
drop policy if exists "Admins delete product images" on storage.objects;
create policy "Admins delete product images" on storage.objects for delete to authenticated using (bucket_id='product-images');

-- Initial catalogue. Safe to run again: existing slugs are updated.
